    int totalMatches, matchPartner[MAXN], reversePartner[MAXN];
    int findMaxMatching(int n, vector<int> adj[]) {
        totalMatches = 0;
        memset(matchPartner, -1, sizeof(matchPartner));
        memset(reversePartner, -1, sizeof(reversePartner));
        for (int i = 0; i < n; i++) {
            memset(used, 0, sizeof(used));
            if (tryMatch(i, adj)) totalMatches++;
        }
        return totalMatches;
    }
private:
    int used[MAXN];
    bool tryMatch(int u, vector<int> adj[]) {
        for (int v : adj[u]) {
            if (!used[v]) {
